{
  "title": "Ticket Lab operations",
  "uid": "dva-ticket",
  "schemaVersion": 39,
  "version": 1,
  "refresh": "5s",
  "time": {
    "from": "now-15m",
    "to": "now"
  },
  "panels": [
    {
      "id": 1,
      "title": "Requests per second",
      "type": "timeseries",
      "gridPos": {
        "x": 0,
        "y": 0,
        "w": 12,
        "h": 9
      },
      "datasource": {
        "type": "prometheus",
        "uid": "dva-prom"
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum by (namespace) (rate(ticket_http_requests_total[1m]))",
          "legendFormat": "{{namespace}}"
        }
      ],
      "fieldConfig": {
        "defaults": {
          "unit": "reqps"
        },
        "overrides": []
      }
    },
    {
      "id": 2,
      "title": "Observed 5xx ratio",
      "type": "timeseries",
      "gridPos": {
        "x": 12,
        "y": 0,
        "w": 12,
        "h": 9
      },
      "datasource": {
        "type": "prometheus",
        "uid": "dva-prom"
      },
      "targets": [
        {
          "refId": "A",
          "expr": "(((sum by (namespace) (rate(ticket_http_requests_total{status=~\"5..\"}[1m]))) or on (namespace) (0 * (sum by (namespace) (rate(ticket_http_requests_total[1m]))))) / (sum by (namespace) (rate(ticket_http_requests_total[1m])))) and on (namespace) ((sum by (namespace) (rate(ticket_http_requests_total[1m]))) > 0)",
          "legendFormat": "{{namespace}}"
        }
      ],
      "fieldConfig": {
        "defaults": {
          "unit": "percentunit",
          "noValue": "N/A"
        },
        "overrides": []
      },
      "description": "Observed 5xx / requests. Zero only with observed traffic. N/A: no traffic or insufficient scrape history; inspect target health separately."
    },
    {
      "id": 3,
      "title": "Successful server latency p95",
      "type": "timeseries",
      "gridPos": {
        "x": 0,
        "y": 9,
        "w": 12,
        "h": 9
      },
      "datasource": {
        "type": "prometheus",
        "uid": "dva-prom"
      },
      "targets": [
        {
          "refId": "A",
          "expr": "histogram_quantile(0.95, sum by (le, namespace) (rate(ticket_http_request_duration_seconds_bucket{status=~\"2..\"}[1m]))) and on (namespace) ((sum by (namespace) (rate(ticket_http_request_duration_seconds_count{status=~\"2..\"}[1m]))) > 0)",
          "legendFormat": "{{namespace}}"
        }
      ],
      "fieldConfig": {
        "defaults": {
          "unit": "s",
          "noValue": "N/A"
        },
        "overrides": []
      },
      "description": "Estimated p95 of observed successful requests. N/A: no successful observations or insufficient scrape history; never interpreted as zero latency."
    },
    {
      "id": 4,
      "title": "Ready observed instances",
      "type": "timeseries",
      "gridPos": {
        "x": 12,
        "y": 9,
        "w": 12,
        "h": 9
      },
      "datasource": {
        "type": "prometheus",
        "uid": "dva-prom"
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum by (namespace) (ticket_ready)",
          "legendFormat": "{{namespace}}"
        }
      ],
      "fieldConfig": {
        "defaults": {
          "unit": "short"
        },
        "overrides": []
      }
    }
  ]
}
